// depends-on-plugin com.intellij.java
// depends-on-plugin org.intellij.groovy
//
// Event-group methods (LivePlugin script).
//
// SCOPE
//   Only .groovy use-sites under kubegroovy/{startup,client,server}_scripts/**.
//
// WHAT IT DOES
//   Reads the project's local/kubegroovy/live-plugin/events/events.json,
//   generated by /kgy generate-typings
//   from the runtime event-handler snapshot, keyed by script side then by
//   runtime group name, and teaches the editor the methods of event-group
//   bindings, e.g. $StartupEvents.registry(...). A NonCodeMembersContributor
//   dispatches on the qualifier name ($StartupEvents, $ServerEvents, ...),
//   so each group only offers its own events; the file's side
//   (startup_scripts, server_scripts, client_scripts) gates which snapshot
//   is used, same convention as the bindings provider.
//   Every synthetic is STATIC (GrLightMethodBuilder, public + static):
//   Groovy resolves static methods through an instance qualifier, and the
//   runtime call shape ($Group.event(...) -> EventHandler.call) is
//   method-shaped for completion and signature help. Registry-shaped
//   handlers collapse to one generic method, e.g.
//   static <T> void registry(ResourceKey<Registry<T>>,
//   Consumer<RegistryKubeEvent<T>>).
//
// LOOKUP / COST
//   Entries are indexed once per file change into
//   Map<side, Map<group, List<entry>>>; the contributor bails fast outside
//   KubeGroovy script dirs, on unqualified references, on unknown qualifier
//   names, or when nameHint matches nothing.
//
// RUNNING IT
//   compile.bat checks it compiles; install.bat copies the script to
//   LivePlugin; reload it from the LivePlugin tool window.

import com.fasterxml.jackson.databind.ObjectMapper
import com.intellij.openapi.diagnostic.Logger
import com.intellij.openapi.project.DumbAware
import com.intellij.psi.JavaPsiFacade
import com.intellij.psi.PsiClass
import com.intellij.psi.PsiClassType
import com.intellij.psi.PsiElement
import org.jetbrains.plugins.groovy.lang.psi.GroovyFile
import com.intellij.psi.PsiFile
import com.intellij.psi.PsiManager
import com.intellij.psi.PsiType
import com.intellij.psi.PsiTypes
import com.intellij.psi.ResolveState
import com.intellij.psi.scope.ElementClassHint
import com.intellij.psi.scope.NameHint
import com.intellij.psi.scope.PsiScopeProcessor
import org.jetbrains.plugins.groovy.lang.psi.api.statements.expressions.GrReferenceExpression
import org.jetbrains.plugins.groovy.lang.psi.impl.synthetic.GrLightMethodBuilder
import org.jetbrains.plugins.groovy.lang.psi.impl.synthetic.GrLightParameter
import org.jetbrains.plugins.groovy.lang.resolve.NonCodeMembersContributor
import org.jetbrains.plugins.groovy.lang.typing.GrTypeCalculator
import org.jetbrains.plugins.groovy.lang.psi.api.statements.expressions.path.GrMethodCallExpression
import org.jetbrains.plugins.groovy.lang.psi.api.statements.expressions.literals.GrLiteral
import com.intellij.openapi.util.Disposer
import com.intellij.openapi.Disposable

class EventMethodParam {
    String name
    String type
}

class EventMethodEntry {
    String name
    String returns
    List<String> typeParams = new ArrayList<String>()
    List<EventMethodParam> params = new ArrayList<EventMethodParam>()
}

class EventMethodConfig {
    Map<String, Map<String, List<EventMethodEntry>>> bySide = new LinkedHashMap<String, Map<String, List<EventMethodEntry>>>()
    Map<String, Set<String>> registriesByElement = [:]
    Map<String, String> elementsByRegistry = [:]
    Map<String, String> defaultBuilders = [:]
    Map<String, Map<String, String>> namedBuilders = [:]
    Map<String, Map<String, Set<String>>> builderAliases = [:]

    void readBuilders(Map parsed) {
        for (def target : (parsed.get('_registryTargets') instanceof Collection ? parsed.get('_registryTargets') : [])) {
            if (!(target instanceof Map) || !(target.key instanceof String) || !(target.elementType instanceof String)) continue
            registriesByElement.computeIfAbsent(target.elementType) { new HashSet<String>() }.add(target.key)
            elementsByRegistry.put(target.key, target.elementType)
        }
        for (def builder : (parsed.get('_builderTypes') instanceof Collection ? parsed.get('_builderTypes') : [])) {
            if (!(builder instanceof Map) || !(builder.registryKey instanceof String) || !(builder.typeId instanceof String) || !(builder.builderType instanceof String)) continue
            String key = builder.registryKey
            String id = builder.typeId
            String type = builder.builderType
            if (builder.defaultType == true) {
                defaultBuilders.put(key, type)
            } else {
                namedBuilders.computeIfAbsent(key) { [:] }.put(id, type)
                String path = id.contains(':') ? id.substring(id.indexOf(':') + 1) : id
                builderAliases.computeIfAbsent(key) { [:] }.computeIfAbsent(path) { new HashSet<String>() }.add(type)
            }
        }
    }

    String builderFor(String element, String id, boolean useDefault) {
        Set<String> registries = registriesByElement.get(element)
        if (registries == null || registries.size() != 1) return null
        String key = registries.iterator().next()
        if (useDefault) return defaultBuilders.get(key)
        // KubeIdentifier treats a bare name as kubegroovy:<name>, then the
        // runtime falls back to the path. Ambiguous paths stay unspecialized.
        String normalized = id.contains(':') ? id : 'kubegroovy:' + id
        String exact = namedBuilders.get(key)?.get(normalized)
        if (exact != null) return exact
        String path = normalized.substring(normalized.indexOf(':') + 1)
        Set<String> aliases = builderAliases.get(key)?.get(path)
        return aliases != null && aliases.size() == 1 ? aliases.iterator().next() : null
    }

    boolean isEmpty() {
        try {
            return bySide.isEmpty()
        } catch (Throwable ignored) {
            return true
        }
    }

    List<EventMethodEntry> forGroup(String side, String group) {
        try {
            Map<String, List<EventMethodEntry>> groups = bySide.get(side)
            if (groups == null) return Collections.emptyList()
            List<EventMethodEntry> l = groups.get(group)
            return l != null ? l : Collections.emptyList()
        } catch (Throwable ignored) {
            return Collections.emptyList()
        }
    }
}

class EventMethodSupport {
    static final Logger LOG = Logger.getInstance("KubeGroovyEventMethods")
    static boolean DEBUG = false
    static final String SYNTHETIC_KIND = "EventGroupMethod"
    static final String EVENT_GROUP_BINDING = "dev.uncandango.kubegroovy.typing.EventGroupBinding"
    static final List<String> SIDES = ["startup", "server", "client"]
    private static File configFile = null
    private static final Map<File, String> configStamps = new HashMap<>()
    private static final Map<File, EventMethodConfig> configs = new HashMap<>()

    static void debug(String message) {
        if (!DEBUG) return
        try {
            LOG.info("[event-methods] " + message)
        } catch (Throwable ignored) {}
    }

    static void setConfigFile(File f) {
        try {
            configFile = f
        } catch (Throwable ignored) {}
    }

    static File configFileFor(PsiElement place) {
        if (configFile != null) return configFile
        String root = place?.getProject()?.getBasePath()
        return root == null || root.isBlank() ? null : new File(root, "local/kubegroovy/live-plugin/events/events.json")
    }

    static synchronized EventMethodConfig load(PsiElement place = null) {
        File source = configFileFor(place)
        EventMethodConfig cached = configs.get(source) ?: new EventMethodConfig()
        try {
            if (source == null || !source.isFile()) return cached
            String stamp = source.lastModified() + ":" + source.length()
            if (stamp == configStamps.get(source)) return cached
            Map parsed = null
            try {
                Object o = new ObjectMapper().readValue(source, Map.class)
                if (o instanceof Map) parsed = (Map) o
            } catch (Throwable t) {
                debug("config parse failed, keeping last good (" + t + ")")
                return cached
            }
            if (parsed == null) return cached
            EventMethodConfig next = new EventMethodConfig()
            next.readBuilders(parsed)
            try {
                for (String side : SIDES) {
                    Object groups = parsed.get(side)
                    if (!(groups instanceof Map)) continue
                    for (def ge : ((Map) groups).entrySet()) {
                        try {
                            if (ge == null || ge.getKey() == null || !(ge.getValue() instanceof Collection)) continue
                            String group = ge.getKey().toString().trim()
                            if (group.isEmpty()) continue
                            List<EventMethodEntry> l = new ArrayList<EventMethodEntry>()
                            for (def e : (Collection) ge.getValue()) {
                                try {
                                    if (!(e instanceof Map)) continue
                                    Map m = (Map) e
                                    Object n = m.get("name")
                                    if (n == null) continue
                                    EventMethodEntry entry = new EventMethodEntry()
                                    entry.name = n.toString().trim()
                                    if (entry.name.isEmpty()) continue
                                    Object r = m.get("returns")
                                    entry.returns = r == null ? "void" : r.toString().trim()
                                    Object tps = m.get("typeParams")
                                    if (tps instanceof Collection) {
                                        for (def tp : (Collection) tps) {
                                            try {
                                                String t = tp == null ? "" : tp.toString().trim()
                                                if (!t.isEmpty()) entry.typeParams.add(t)
                                            } catch (Throwable ignored2) {}
                                        }
                                    }
                                    Object ps = m.get("params")
                                    if (ps instanceof Collection) {
                                        for (def p : (Collection) ps) {
                                            try {
                                                if (!(p instanceof Map)) continue
                                                Map pm = (Map) p
                                                Object pn = pm.get("name")
                                                Object pt = pm.get("type")
                                                if (pn == null || pt == null) continue
                                                EventMethodParam param = new EventMethodParam()
                                                param.name = pn.toString().trim()
                                                param.type = pt.toString().trim()
                                                if (param.name.isEmpty() || param.type.isEmpty()) continue
                                                entry.params.add(param)
                                            } catch (Throwable ignored2) {}
                                        }
                                    }
                                    l.add(entry)
                                } catch (Throwable ignored2) {}
                            }
                            if (l.isEmpty()) continue
                            Map<String, List<EventMethodEntry>> byGroup = next.bySide.get(side)
                            if (byGroup == null) {
                                byGroup = new LinkedHashMap<String, List<EventMethodEntry>>()
                                next.bySide.put(side, byGroup)
                            }
                            byGroup.put(group, l)
                        } catch (Throwable ignored2) {}
                    }
                }
            } catch (Throwable ignored) {}
            cached = next
            configs.put(source, next)
            configStamps.put(source, stamp)
            debug("config loaded sides=" + next.bySide.keySet())
        } catch (Throwable ignored) {}
        return cached
    }

    // Check the use-site, never the declaration being resolved. Completion copies
    // retain their original file; scratch files and unknown contexts fail closed.
    static String sideForFile(PsiFile file) {
        if (!(file instanceof GroovyFile)) return null
        PsiFile original = file.getOriginalFile()
        if (!(original instanceof GroovyFile)) return null
        String path = original.getVirtualFile()?.getPath()?.replace('\\', '/')
        if (path == null || !path.endsWith('.groovy')) return null
        def match = (path =~ /(?:^|\/)kubegroovy\/(startup|client|server)_scripts\/.+\.groovy$/)
        return match.find() ? match.group(1) : null
    }

    static boolean accepts(PsiScopeProcessor processor, ElementClassHint.DeclarationKind... kinds) {
        try {
            def hint = processor.getHint(ElementClassHint.KEY)
            if (hint == null) return true
            for (def kind : kinds) {
                try {
                    if (hint.shouldProcess(kind)) return true
                } catch (Throwable ignored) {}
            }
            return false
        } catch (Throwable ignored) {
            return true
        }
    }

    /**
     * Parses a fully-qualified (possibly generic) type text against the light
     * method being built, so method-level type variables (e.g. T in
     * ResourceKey<Registry<T>>) resolve. Null when unparseable — the caller
     * falls back to Object/void instead of failing resolution. This is the
     * fallback for {@link #buildTreeType}: a fragment reference may share the
     * variable's name without being the same object, which renders fine but
     * gives call-site inference nothing to solve.
     */
    static PsiType parseType(String text, GrLightMethodBuilder context, def factory) {
        if (text == null || context == null || factory == null) return null
        try {
            String t = text.trim()
            if (t.isEmpty()) return null
            return factory.createTypeFromText(t, context)
        } catch (Throwable ignored) {
            return null
        }
    }

    // PARSER-BEGIN (mirror of dev.uncandango.kubegroovy.typing.TypeTree.parse:
    // name (< type (, type)* >)? ([])* over dotted identifiers; null outside
    // that grammar. Kept dependency-free on purpose — scripts must run in any
    // project, so they cannot import mod classes. Trees are Maps:
    // [name:, args:, arrays:].)
    static Map parseTypeTree(String text) {
        try {
            if (text == null) return null
            List<String> chars = text.toList()
            int[] at = [0]
            Map tree = parseTreeType(chars, at)
            if (tree == null) return null
            skipTreeWs(chars, at)
            if (at[0] < chars.size()) return null
            return tree
        } catch (Throwable ignored) {
            return null
        }
    }

    private static void skipTreeWs(List<String> chars, int[] at) {
        try {
            while (at[0] < chars.size() && Character.isWhitespace(chars[at[0]].charAt(0))) at[0]++
        } catch (Throwable ignored) {}
    }

    private static String parseTreeName(List<String> chars, int[] at) {
        try {
            int start = at[0]
            while (at[0] < chars.size()) {
                String ch = chars[at[0]]
                char c = ch.charAt(0)
                if (Character.isJavaIdentifierPart(c) || c == '.' as char) at[0]++
                else break
            }
            if (at[0] == start) return null
            String name = chars[start..<at[0]].join("")
            for (String segment : name.split("\\.", -1)) {
                if (segment.isEmpty() || !Character.isJavaIdentifierStart(segment.charAt(0))) return null
                for (int i = 1; i < segment.length(); i++) {
                    if (!Character.isJavaIdentifierPart(segment.charAt(i))) return null
                }
            }
            return name
        } catch (Throwable ignored) {
            return null
        }
    }

    private static Map parseTreeType(List<String> chars, int[] at) {
        try {
            skipTreeWs(chars, at)
            String name = parseTreeName(chars, at)
            if (name == null) return null
            skipTreeWs(chars, at)
            List<Map> args = new ArrayList<Map>()
            if (at[0] < chars.size() && chars[at[0]] == "<") {
                at[0]++
                Map first = parseTreeType(chars, at)
                if (first == null) return null
                args.add(first)
                skipTreeWs(chars, at)
                while (at[0] < chars.size() && chars[at[0]] == ",") {
                    at[0]++
                    Map next = parseTreeType(chars, at)
                    if (next == null) return null
                    args.add(next)
                    skipTreeWs(chars, at)
                }
                if (at[0] >= chars.size() || chars[at[0]] != ">") return null
                at[0]++
            }
            int arrays = 0
            for (;;) {
                skipTreeWs(chars, at)
                if (at[0] + 1 < chars.size() && chars[at[0]] == "[" && chars[at[0] + 1] == "]") {
                    arrays++
                    at[0] += 2
                } else {
                    break
                }
            }
            return [name: name, args: args, arrays: arrays]
        } catch (Throwable ignored) {
            return null
        }
    }
    // PARSER-END

    static PsiType objectType(def factory, PsiManager mgr, def scope) {
        try {
            PsiType t = factory.createTypeByFQClassName("java.lang.Object", scope)
            if (t != null) return t
        } catch (Throwable ignored) {}
        try {
            return PsiType.getJavaLangObject(mgr, scope)
        } catch (Throwable ignored) {
            return null
        }
    }

    /**
     * Per-lookup workspace: the PSI factory/scope new types are created in.
     */
    static class EventTypeCtx {
        final def factory
        final def project
        final def scope

        EventTypeCtx(def factory, def project, def scope) {
            this.factory = factory
            this.project = project
            this.scope = scope
        }

        PsiClass findClass(String fqn) {
            if (fqn == null || project == null || scope == null) return null
            try {
                return JavaPsiFacade.getInstance(project).findClass(fqn, scope)
            } catch (Throwable ignored) {
                return null
            }
        }
    }

    /**
     * Identity-preserving reference to the synthetic's own type variable.
     * A same-named fragment is not enough: inference
     * ({@code T = Block}) needs the reference to resolve to the method's
     * declared type parameter object. Null unless that identity holds —
     * the caller then falls back to the full-text fragment (renders the
     * same, just without inference).
     */
    static PsiType ownTypeVariable(String name, GrLightMethodBuilder synth, EventTypeCtx c) {
        try {
            if (name == null || synth == null || c == null || c.factory == null) return null
            def ours = null
            try {
                for (def tp : synth.getTypeParameters()) {
                    try {
                        if (tp != null && name.equals(tp.getName())) {
                            ours = tp
                            break
                        }
                    } catch (Throwable ignored2) {}
                }
            } catch (Throwable ignored) {}
            if (ours == null) return null
            // Build directly from the declaration: fragments do not necessarily
            // resolve a light method's type parameters in the Groovy resolver.
            return c.factory.createType(ours)
        } catch (Throwable ignored) {
            return null
        }
    }

    /**
     * Assembles a parsed tree inside-out so nested type variables keep
     * method-level identity (see {@link #ownTypeVariable}). Null on any
     * failure — the caller falls back to the full-text fragment, then
     * Object/void. Strictly better-or-equal: rendering can never regress.
     */
    static PsiType buildTreeType(Map tree, GrLightMethodBuilder synth, Set<String> typeVars, EventTypeCtx c) {
        try {
            if (tree == null || synth == null || c == null || c.factory == null) return null
            String name = null
            try {
                name = tree.get("name")?.toString()
            } catch (Throwable ignored) {}
            if (name == null || name.isEmpty()) return null
            List subs = []
            try {
                def a = tree.get("args")
                if (a instanceof List) subs = (List) a
            } catch (Throwable ignored) {}
            List<PsiType> argTypes = new ArrayList<PsiType>()
            for (def sub : subs) {
                try {
                    if (!(sub instanceof Map)) return null
                    PsiType at = buildTreeType((Map) sub, synth, typeVars, c)
                    if (at == null) return null
                    argTypes.add(at)
                } catch (Throwable ignored2) {
                    return null
                }
            }
            PsiType base = null
            try {
                if (argTypes.isEmpty() && !name.contains(".") && typeVars.contains(name)) {
                    base = ownTypeVariable(name, synth, c)
                    if (base == null) return null
                } else {
                    PsiClass cls = c.findClass(name)
                    if (cls == null) return null
                    base = argTypes.isEmpty()
                        ? c.factory.createType(cls)
                        : c.factory.createType(cls, argTypes.toArray(new PsiType[0]))
                }
            } catch (Throwable ignored) {
                return null
            }
            int arrays = 0
            try {
                arrays = Integer.parseInt(tree.get("arrays")?.toString() ?: "0")
            } catch (Throwable ignored) {}
            for (int i = 0; i < arrays; i++) {
                try {
                    base = base.createArrayType()
                } catch (Throwable ignored2) {
                    return null
                }
            }
            return base
        } catch (Throwable ignored) {
            return null
        }
    }

    /**
     * Builds one static synthetic from a JSON entry. All synthetics are
     * static by design (see file doc): Groovy calls them through the
     * instance qualifier.
     */
    static GrLightMethodBuilder buildMethod(EventMethodEntry entry, PsiClass containing,
            def factory, PsiManager mgr, def scope) {
        PsiManager m = mgr
        try {
            if (m == null) m = containing.getManager()
        } catch (Throwable ignored) {}
        GrLightMethodBuilder synth = new GrLightMethodBuilder(m, entry.name)
        synth.setContainingClass(containing)
        try {
            synth.setModifiers(["public", "static"] as String[])
        } catch (Throwable ignored) {}
        Set<String> typeVars = new HashSet<String>()
        try {
            for (String tp : entry.typeParams) {
                try {
                    if (tp != null && !tp.isEmpty()) {
                        synth.addTypeParameter(tp)
                        typeVars.add(tp)
                    }
                } catch (Throwable ignored2) {}
            }
        } catch (Throwable ignored) {}
        EventTypeCtx tc = null
        try {
            tc = new EventTypeCtx(factory, containing.getProject(), scope)
        } catch (Throwable ignored) {}
        try {
            PsiType ret = null
            try {
                if ("void".equals(entry.returns)) ret = PsiTypes.voidType()
                else {
                    ret = buildTreeType(parseTypeTree(entry.returns), synth, typeVars, tc)
                    if (ret == null) ret = parseType(entry.returns, synth, factory)
                }
            } catch (Throwable ignored2) {}
            if (ret == null && !"void".equals(entry.returns)) {
                try {
                    ret = objectType(factory, m, scope)
                } catch (Throwable ignored2) {}
            }
            if (ret != null) synth.setReturnType(ret)
        } catch (Throwable ignored) {}
        try {
            int i = 0
            for (EventMethodParam p : entry.params) {
                try {
                    String pname = (p.name == null || p.name.isEmpty()) ? "arg" + i : p.name
                    PsiType ptype = buildTreeType(parseTypeTree(p.type), synth, typeVars, tc)
                    if (ptype == null) ptype = parseType(p.type, synth, factory)
                    if (ptype == null) ptype = objectType(factory, m, scope)
                    synth.addParameter(new GrLightParameter(pname, ptype, synth))
                } catch (Throwable ignored2) {}
                i++
            }
        } catch (Throwable ignored) {}
        try {
            synth.setNavigationElement(containing)
        } catch (Throwable ignored) {}
        try {
            synth.setMethodKind(SYNTHETIC_KIND)
        } catch (Throwable ignored) {}
        try {
            synth.setOriginInfo(SYNTHETIC_KIND)
        } catch (Throwable ignored) {}
        return synth
    }

    /**
     * Registry targets are coerced at runtime, but the object-overload provider
     * sees declared Java members only. Supply that bridge here, alongside the
     * synthetic generic signature. Known literal keys also determine T; replacing
     * ResourceKey with Object alone would discard that inference constraint.
     */
    static EventMethodEntry registryCoercionMethod(EventMethodEntry entry, GrReferenceExpression place, EventMethodConfig config) {
        if (entry.typeParams.size() != 1 || entry.params.size() != 2) return null
        String variable = entry.typeParams[0]
        Map target = parseTypeTree(entry.params[0].type)
        if (target?.name != 'net.minecraft.resources.ResourceKey' || target.args.size() != 1) return null
        Map registry = target.args[0]
        if (registry?.name != 'net.minecraft.core.Registry' || registry.args.size() != 1 || registry.args[0].name != variable) return null
        Map consumer = parseTypeTree(entry.params[1].type)
        if (consumer?.name != 'java.util.function.Consumer' || consumer.args.size() != 1) return null
        Map event = consumer.args[0]
        if (event.args.size() != 1 || event.args[0].name != variable) return null
        String element = '?'
        def call = place.getParent()
        if (call instanceof GrMethodCallExpression && call.getInvokedExpression().is(place)) {
            def positional = call.getArgumentList()?.getExpressionArguments()
            if (positional != null && positional.length > 0 && positional[0] instanceof GrLiteral) {
                def value = positional[0].getValue()
                if (value instanceof String) {
                    String key = value.contains(':') ? value : 'minecraft:' + value
                    element = config.elementsByRegistry.get(key) ?: '?'
                }
            }
        }
        return new EventMethodEntry(name: entry.name, returns: entry.returns, params: [
            new EventMethodParam(name: entry.params[0].name, type: 'java.lang.Object'),
            new EventMethodParam(name: entry.params[1].name, type: "java.util.function.Consumer<${event.name}<${element}>>")
        ])
    }
}

class EventMethodsContributor extends NonCodeMembersContributor implements DumbAware {
    @Override
    void processDynamicElements(PsiType qualifierType, PsiScopeProcessor processor, PsiElement place, ResolveState state) {
        if (!(place instanceof GrReferenceExpression)) {
            EventMethodSupport.debug("contributor: place is not a reference (" + place?.getClass()?.getName() + ")")
            return
        }
        GrReferenceExpression ref = (GrReferenceExpression) place
        def qualifier = null
        try {
            qualifier = ref.getQualifierExpression()
        } catch (Throwable ignored) {
            return
        }
        if (!(qualifier instanceof GrReferenceExpression)) return
        String group = null
        try {
            group = ((GrReferenceExpression) qualifier).getReferenceName()
        } catch (Throwable ignored) {
            return
        }
        if (group == null || group.isEmpty()) return
        if (!EventMethodSupport.accepts(processor, ElementClassHint.DeclarationKind.METHOD)) return
        String wanted = null
        try {
            def hint = processor.getHint(NameHint.KEY)
            if (hint != null) wanted = hint.getName(state)
        } catch (Throwable ignored) {}
        String side = null
        try {
            side = EventMethodSupport.sideForFile(place.getContainingFile())
        } catch (Throwable ignored) {}
        if (side == null) {
            EventMethodSupport.debug("contributor: no side for file=" + place?.getContainingFile())
            return
        }
        EventMethodConfig config = EventMethodSupport.load(place)
        List<EventMethodEntry> entries = config.forGroup(side, group)
        if (entries.isEmpty()) return
        EventMethodSupport.debug("contributor: side=" + side + " group=" + group + " wanted=" + wanted + " entries=" + entries.size())
        PsiManager mgr = null
        try {
            mgr = place.getManager()
        } catch (Throwable ignored) {}
        if (mgr == null) return
        def scope = null
        try {
            scope = place.getResolveScope()
        } catch (Throwable ignored) {}
        PsiClass containing = null
        try {
            containing = JavaPsiFacade.getInstance(place.getProject())
                .findClass(EventMethodSupport.EVENT_GROUP_BINDING, scope)
        } catch (Throwable ignored) {}
        if (containing == null) {
            EventMethodSupport.debug("contributor: EventGroupBinding not on classpath")
            return
        }
        def factory = null
        try {
            factory = JavaPsiFacade.getInstance(place.getProject()).getElementFactory()
        } catch (Throwable ignored) {}
        if (factory == null) return
        for (EventMethodEntry entry : entries) {
            if (entry == null) continue
            try {
                if (wanted != null && !wanted.equals(entry.name)) continue
                def synth = EventMethodSupport.buildMethod(entry, containing, factory, mgr, scope)
                if (synth == null) continue
                try {
                    if (!processor.execute(synth, state)) return
                    def bridge = EventMethodSupport.registryCoercionMethod(entry, ref, config)
                    if (bridge != null && !processor.execute(EventMethodSupport.buildMethod(bridge, containing, factory, mgr, scope), state)) return
                } catch (Throwable ignored2) {}
            } catch (Throwable ignored2) {}
        }
    }
}

/** Specializes only registry create calls; the actual Java method still resolves normally. */
class RegistryBuilderTypeCalculator implements GrTypeCalculator<GrMethodCallExpression>, DumbAware {
    @Override
    PsiType getType(GrMethodCallExpression call) {
        if (EventMethodSupport.sideForFile(call?.getContainingFile()) == null) return null
        def invoked = call.getInvokedExpression()
        if (!(invoked instanceof GrReferenceExpression) || invoked.getReferenceName() != 'create') return null
        def args = call.getArgumentList()
        if (args == null || args.getNamedArguments().length != 0 || call.getClosureArguments().length != 0) return null
        def positional = args.getExpressionArguments()
        if (positional.length != 1 && positional.length != 2) return null
        String id = null
        if (positional.length == 2) {
            if (!(positional[1] instanceof GrLiteral) || !(positional[1].getValue() instanceof String)) return null
            id = positional[1].getValue()
        }
        PsiType qualifier = invoked.getQualifierExpression()?.getType()
        if (!(qualifier instanceof PsiClassType)) return null
        def resolved = qualifier.resolveGenerics()
        PsiClass event = resolved.getElement()
        if (event?.getQualifiedName() != 'dev.uncandango.kubegroovy.registry.RegistryKubeEvent' &&
                event?.getQualifiedName() != 'dev.uncandango.kubegroovy.registry.ServerRegistryKubeEvent') return null
        if (event.getTypeParameters().length != 1) return null
        PsiType element = resolved.getSubstitutor().substitute(event.getTypeParameters()[0])
        if (element == null) return null
        String builder = EventMethodSupport.load(call).builderFor(element.getCanonicalText(), id, positional.length == 1)
        if (builder == null) return null
        PsiClass cls = JavaPsiFacade.getInstance(call.getProject()).findClass(builder, call.getResolveScope())
        if (cls == null) return null
        return JavaPsiFacade.getElementFactory(call.getProject()).createType(cls)
    }
}

// --- LivePlugin registration (unregistered automatically via pluginDisposable) ---
try {
    com.intellij.openapi.extensions.ExtensionPointName.create("org.intellij.groovy.membersContributor").point
        .registerExtension(new EventMethodsContributor(), pluginDisposable)
} catch (Throwable ignored) {}
try {
    def calculator = new RegistryBuilderTypeCalculator()
    GrTypeCalculator.EP.addExplicitExtension(GrMethodCallExpression, calculator)
    Disposer.register(pluginDisposable, { ->
        GrTypeCalculator.EP.removeExplicitExtension(GrMethodCallExpression, calculator)
    } as Disposable)
} catch (Throwable ignored) {}